function solve(operations) {
    const history = [''];
    let at = 0;
    const out = [];
    for (const op of operations) {
        if (op[0] === 'type') {
            history.length = at + 1;
            history.push(history[at] + op[1]);
            at += 1;
        } else if (op[0] === 'delete') {
            history.length = at + 1;
            const cur = history[at];
            history.push(op[1] >= cur.length ? '' : cur.slice(0, cur.length - op[1]));
            at += 1;
        } else if (op[0] === 'undo') {
            if (at > 0) at -= 1;
        } else if (op[0] === 'redo') {
            if (at < history.length - 1) at += 1;
        } else {
            out.push(history[at]);
        }
    }
    return out;
}

