function solve(capacity, operations) {
    const buf = new Array(capacity).fill(0);
    let head = 0;
    let size = 0;
    const out = [];
    for (const op of operations) {
        const type = op[0];
        if (type === 'enqueue') {
            if (size === capacity) {
                out.push(false);
            } else {
                buf[(head + size) % capacity] = op[1];
                size += 1;
                out.push(true);
            }
        } else if (type === 'dequeue') {
            if (size === 0) {
                out.push(false);
            } else {
                head = (head + 1) % capacity;
                size -= 1;
                out.push(true);
            }
        } else if (type === 'front') {
            out.push(size === 0 ? -1 : buf[head]);
        } else if (type === 'rear') {
            out.push(size === 0 ? -1 : buf[(head + size - 1) % capacity]);
        } else if (type === 'isEmpty') {
            out.push(size === 0);
        } else {
            out.push(size === capacity);
        }
    }
    return out;
}

