function solve(words, order) {
    const rank = {};
    for (let i = 0; i < order.length; i++) rank[order[i]] = i;
    const compare = (a, b) => {
        const n = Math.min(a.length, b.length);
        for (let i = 0; i < n; i++) {
            if (a[i] !== b[i]) return rank[a[i]] - rank[b[i]];
        }
        return a.length - b.length;
    };
    return [...words].sort(compare);
}

