function solve(buildings) {
    const xs = [...new Set(buildings.flatMap(([l, r]) => [l, r]))].sort((a, b) => a - b);
    const out = [];
    let last = 0;
    for (const x of xs) {
        let h = 0;
        for (const [l, r, height] of buildings) {
            if (l <= x && x < r && height > h) h = height;
        }
        if (h !== last) {
            out.push([x, h]);
            last = h;
        }
    }
    return out;
}

