function solve(board, words) {
    const rows = board.length;
    if (rows === 0) return [];
    const cols = board[0].length;
    const root = { children: new Map(), word: null };
    for (const w of words) {
        let node = root;
        for (const ch of w) {
            if (!node.children.has(ch)) node.children.set(ch, { children: new Map(), word: null });
            node = node.children.get(ch);
        }
        node.word = w;
    }
    const found = new Set();
    const seen = board.map((row) => row.map(() => false));
    const dirs = [[1, 0], [-1, 0], [0, 1], [0, -1]];
    const dfs = (r, c, node) => {
        const next = node.children.get(board[r][c]);
        if (!next) return;
        if (next.word !== null) found.add(next.word);
        seen[r][c] = true;
        for (const [dr, dc] of dirs) {
            const nr = r + dr;
            const nc = c + dc;
            if (nr >= 0 && nr < rows && nc >= 0 && nc < cols && !seen[nr][nc]) dfs(nr, nc, next);
        }
        seen[r][c] = false;
    };
    for (let r = 0; r < rows; r++) {
        for (let c = 0; c < cols; c++) dfs(r, c, root);
    }
    return [...found].sort();
}

